<?php
$tools=query('SELECT f.id,f.nome,c.fornecedor_id FROM ferramentas f JOIN ferramenta_comercial c ON c.ferramenta_id=f.id ORDER BY f.nome')->fetchAll();$suppliers=query('SELECT id,nome FROM fornecedores WHERE ativo=1 ORDER BY nome')->fetchAll();
$rows=query('SELECT d.*,u.nome responsavel FROM compras_documentos d JOIN usuarios u ON u.id=d.usuario_id ORDER BY d.id DESC LIMIT 100')->fetchAll();$draft=$_SESSION['compra_form']??[];$view=null;$items=[];
if(isset($_GET['ver'])){$view=query('SELECT * FROM compras_documentos WHERE id=?',[(int)$_GET['ver']])->fetch();if($view)$items=query('SELECT c.* FROM compras_estoque c JOIN compras_documento_itens i ON i.compra_id=c.id WHERE i.documento_id=? ORDER BY c.id',[$view['id']])->fetchAll();}
page('Compras e entradas');?>
<section class="card"><h2>Registrar compra recebida</h2><p>Escolha um fornecedor e informe as quantidades e custos dos itens recebidos. Todos ficam no mesmo documento e entram no estoque juntos.</p><form method="post" class="form-grid" id="purchase-form"><?php csrf();?><input type="hidden" name="action" value="save_purchase"><input type="hidden" name="chave" value="<?=e($draft['chave']??bin2hex(random_bytes(32)))?>">
<label>Fornecedor<select name="fornecedor_id" required><option value="">Selecione</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>" <?=($draft['fornecedor_id']??0)==$s['id']?'selected':''?>><?=e($s['nome'])?></option><?php endforeach;?></select></label><label>Data da compra<input type="date" name="data_compra" min="1900-01-01" max="<?=date('Y-m-d')?>" value="<?=e($draft['data_compra']??date('Y-m-d'))?>" required></label><label>Nº da nota / documento (opcional)<input name="referencia" maxlength="120" value="<?=e($draft['referencia']??'')?>"></label>
<div class="table-wrap order-items"><table><thead><tr><th>ID</th><th>Ferramenta</th><th>Quantidade</th><th>Custo unitário (R$)</th></tr></thead><tbody><?php foreach($tools as $t):?><tr data-supplier="<?=$t['fornecedor_id']?>"><td><?=$t['id']?></td><td><?=e($t['nome'])?></td><td><input type="number" name="quantidades[<?=$t['id']?>]" min="0" max="1000000" value="<?=e($draft['quantidades'][$t['id']]??0)?>" aria-label="Quantidade de <?=e($t['nome'])?>"></td><td><input name="custos[<?=$t['id']?>]" inputmode="decimal" maxlength="20" value="<?=e($draft['custos'][$t['id']]??'')?>" placeholder="0,00" aria-label="Custo de <?=e($t['nome'])?>"></td></tr><?php endforeach;?></tbody></table></div>
<div class="form-footer"><strong>Total estimado: <span id="purchase-total">R$ 0,00</span></strong><button>Registrar compra e adicionar estoque</button></div></form><p>Use apenas para mercadorias já recebidas. Ajustes manuais de estoque não devem repetir estas unidades. Cada compra é de um fornecedor; para outro fornecedor, registre outro documento.</p></section>
<?php if($view):?><section class="card"><h2>Compra #<?=$view['id']?> — <?=e($view['fornecedor_nome'])?></h2><p><?=e($view['data_compra'])?> · Documento: <?=e($view['referencia'])?> · <?=e($view['status'])?></p><div class="table-wrap"><table><thead><tr><th>ID ferramenta</th><th>Item</th><th>Quantidade</th><th>Custo</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=$i['ferramenta_id']?></td><td><?=e($i['ferramenta_nome'])?></td><td><?=$i['quantidade']?></td><td><?=money($i['custo_unitario'])?></td><td><?=money($i['total'])?></td></tr><?php endforeach;?></tbody></table></div><p><b>Total: <?=money($view['total'])?></b></p><?php if(admin()&&$view['status']==='Registrada'):?><form method="post" class="stack" data-confirm="Cancelar todo o documento e retirar suas unidades do estoque?"><?php csrf();?><input type="hidden" name="id" value="<?=$view['id']?>"><label>Motivo do cancelamento<input name="motivo" maxlength="255" required></label><button name="action" value="cancel_purchase" class="danger">Cancelar compra completa</button></form><?php endif;?></section><?php endif;?>
<section class="card"><h2>Últimos 100 documentos</h2><div class="table-wrap"><table><thead><tr><th>Nº</th><th>Fornecedor</th><th>Data</th><th>Documento</th><th>Total</th><th>Status</th><th>Responsável</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['fornecedor_nome'])?></td><td><?=e($r['data_compra'])?></td><td><?=e($r['referencia'])?></td><td><?=money($r['total'])?></td><td><?=e($r['status'])?></td><td><?=e($r['responsavel'])?></td><td><a href="index.php?p=compras&ver=<?=$r['id']?>">Ver itens</a></td></tr><?php endforeach;if(!$rows)emptyRow(8);?></tbody></table></div></section><?php endpage();
